using UnityEngine;using UnityEngine.InputSystem;
[DefaultExecutionOrder(150)] public class WoodlandSuitIntegrity:MonoBehaviour {
 WoodlandPlayer player;WoodlandInventory inventory;WoodlandAnatomy body;bool patching;float notify;Transform patch;Material patchMaterial;
 void Start(){player=GetComponent<WoodlandPlayer>();inventory=player.inventory;body=player.anatomy;body.HitOccurred+=Damage;}
 void Damage(BodyRegion r,float damage,Vector3 point,Vector3 direction){var suit=inventory.Find("suit");if(suit==null||damage<=0)return;suit.condition=Mathf.Max(0,suit.condition-Mathf.Clamp(damage*.8f,8,45));inventory.Notify("SUIT BREACH — hold P to seal with an adhesive patch.");}
 void Update(){if(WoodlandDemoControls.Paused)return;if(!inventory||body.Dead)return;var suit=inventory.Find("suit");if(suit==null)return;if(suit.condition<99){suit.contamination=Mathf.Min(100,suit.contamination+Time.deltaTime*(100-suit.condition)*.0007f);suit.filter=Mathf.Max(0,suit.filter-Time.deltaTime*.04f);if(Time.time>notify){notify=Time.time+10;inventory.Notify("Suit breach • Hold P to patch • "+inventory.Count("suit_patch")+" patches");}}
 var k=Keyboard.current;if(k==null)return;if(k.pKey.wasPressedThisFrame&&suit.condition<99&&!player.cinematicLocked&&!player.fieldKit.Busy&&!player.equipment.ActionBusy)patching=player.equipment.UseSupply("suit_patch");if(patching&&!k.pKey.isPressed){if(player.equipment.ActiveSupply=="suit_patch")player.equipment.CancelSupply();patching=false;}}
 void LateUpdate(){if(!player)return;bool active=player.equipment.ActionBusy&&player.equipment.ActiveSupply=="suit_patch";if(active&&!patch){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name="Adhesive suit repair patch";Destroy(g.GetComponent<Collider>());patch=g.transform;patch.SetParent(player.eye.transform,false);patch.localScale=new Vector3(.055f,.003f,.075f);patchMaterial=new Material(Shader.Find("Universal Render Pipeline/Lit"));patchMaterial.color=new Color(.08f,.105f,.07f);g.GetComponent<Renderer>().sharedMaterial=patchMaterial;}if(patch)patch.gameObject.SetActive(active);if(active){var pose=GetComponent<WoodlandCombatPresentation>();if(pose&&pose.bandageWrap){pose.bandageWrap.gameObject.SetActive(false);patch.position=pose.bandageWrap.position;patch.rotation=pose.bandageWrap.rotation;}}}
 void OnDestroy(){if(patch)Destroy(patch.gameObject);if(patchMaterial)Destroy(patchMaterial);if(body)body.HitOccurred-=Damage;}
}
